const timingOption=storyLabel('Offer to retime pictures, captions and camera after replacing narration',Object.assign(document.createElement('input'),{type:'checkbox',id:'offerNarrationVisualTiming',checked:true}));$('narrationContinueVisuals').closest('label').after(timingOption);
function planNarrationVisualTiming(before,after,oldClips,newClips){if(!oldClips.length||!newClips.length)throw Error('Both the previous and replacement narration are needed.');const start=Math.min(...oldClips.map(c=>c.start)),oldEnd=Math.max(...oldClips.map(audioEnd)),newEnd=Math.max(...newClips.map(audioEnd)),delta=newEnd-oldEnd,scale=(newEnd-start)/(oldEnd-start),map=t=>t<=start?t:t>=oldEnd?t+delta:start+(t-start)*scale,p=structuredClone(after),newIds=new Set(newClips.map(c=>c.id)),offsets=new Map();let oldOffset=0;for(const s of before.scenes){offsets.set(s.id,oldOffset);oldOffset+=s.duration}p.scenes=before.scenes.map(original=>{const source=structuredClone(original),oldOffset=offsets.get(source.id),nextOffset=map(oldOffset),duration=map(oldOffset+source.duration)-nextOffset,local=t=>Math.max(0,map(oldOffset+t)-nextOffset);if(duration<1||duration>60)throw Error('A retimed scene would exceed the 1–60 second scene range. Keep the new narration and adjust scene boundaries before retiming visuals.');source.duration=duration;const keys=list=>{for(const k of list||[])k.t=local(k.t)};for(const o of source.objects){o.in=local(clipStart(o));o.out=local(clipEnd(o,original));keys(o.keys);for(const name of ['expressionKeys','viewKeys','handGestureKeys'])keys(o[name]);for(const track of Object.values(o.bodyAnimation||{}))keys(track.keys);for(const track of Object.values(o.objectAnimation||{}))keys(track);for(const b of [...(o.actionBlocks||[]),...(o.directedPoints||[])]){const before=b.duration,end=local(b.start+b.duration);b.start=local(b.start);b.duration=end-b.start;if(b.directorTimeMap)for(const field of ['sourceDuration','from','to'])b.directorTimeMap[field]*=b.duration/before}for(const pin of o.footPins||[]){pin.start=local(pin.start);pin.end=local(pin.end)}if(o.motionPath){o.motionPath.start=local(o.motionPath.start);o.motionPath.end=local(o.motionPath.end)}for(const w of o.wordAnimation?.words||[]){const end=local(w.start+w.duration);w.start=local(w.start);w.duration=end-w.start}delete o.timelinePlayback}for(const c of source.captions||[]){c.start=local(c.start);c.end=local(c.end);for(const w of c.words||[]){w.start=local(w.start);w.end=local(w.end)}}for(const c of source.storyCues||[]){const end=local(c.at+c.duration);c.at=local(c.at);c.duration=end-c.at}for(const c of source.storyShots||[])c.at=local(c.at);for(const c of source.propInteractions||[]){const end=local(c.start+c.duration);c.start=local(c.start);c.duration=end-c.start}if(source.cameraPath){source.cameraPath.start=local(source.cameraPath.start);source.cameraPath.end=local(source.cameraPath.end)}for(const k of source.resizeCameraKeys||[])k.t=local(k.t);const updated=p.scenes.find(s=>s.id===source.id);source.dialogue=structuredClone(storyLines(updated||source));return source});for(const c of p.audioClips||[])if(!newIds.has(c.id))c.start=map(c.start);const group=newClips[0].longVoiceGroupId;if(group){const root=narrationRoot(after,group);rebuildNarrationGroup(p,group,structuredClone(newClips),root)}else{for(const s of p.scenes)for(const l of storyLines(s))if(l.audioId===newClips[0].id){const c=newClips[0];l.start=c.start-storySceneOffsetFor(p,s);l.duration=Math.max(.1,c.duration);l.manualStart=l.start}}if(!valid(p))throw Error('Some linked clips cannot fit this timing safely. The replacement narration is kept; visuals were not changed.');return{project:p,delta,source:JSON.stringify(after)}}
function storySceneOffsetFor(p,s){return p.scenes.slice(0,p.scenes.indexOf(s)).reduce((n,s)=>n+s.duration,0)}
function offerVisualTiming(plan){pendingVisualTiming=plan;const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Keep the pictures in time?</h2><p>The replacement narration changes the timing by '+plan.delta.toFixed(2)+' seconds. This adjustment retimes pictures, captions and camera shots, and shifts following scenes.</p>';dialog.append(storyButton('Preview timing',()=>{const s=plan.project.scenes[sceneIndex];const canvas=document.createElement('canvas');canvas.width=640;canvas.height=360;const original=project;try{project=plan.project;renderSceneFrame(canvas.getContext('2d'),s,Math.min(time,s.duration))}finally{project=original}dialog.append(canvas)}),storyButton('Apply timing',()=>{if(JSON.stringify(project)!==plan.source)return toast('The project changed. Review the timing again.');Object.assign(project,plan.project);save();render();hydrateAudio();dialog.close()}),storyButton('Keep current visual timing',()=>dialog.close()));dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()}
const addBeforeVisualTiming=$('addOfflineVoice').onclick;$('addOfflineVoice').onclick=async()=>{const context=offlineVoiceContext,before=structuredClone(project),line=context?.line,oldClips=line?.audioId?narrationGroupClips(tracks().find(c=>c.id===line.audioId)||{}):[],offer=$('offerNarrationVisualTiming').checked;await addBeforeVisualTiming();if(!offer||!oldClips.length||$('offlineVoiceDialog').open)return;const newLine=offlineVoiceContext?.line,c=tracks().find(c=>c.id===newLine?.audioId);if(!c)return;const next=narrationGroupClips(c);if(Math.abs(next.reduce((n,c)=>n+c.duration,0)-oldClips.reduce((n,c)=>n+c.duration,0))<.02)return;try{offerVisualTiming(planNarrationVisualTiming(before,project,oldClips,next))}catch(e){toast(e.message)}};
